<script setup lang="ts">import{ref,onMounted,onUnmounted}from'vue';import{api,errorMessage}from'../api';import PageHeader from'../components/PageHeader.vue';import Modal from'../components/Modal.vue';import DataTable from'../components/DataTable.vue';import StatusBadge from'../components/StatusBadge.vue';import{Plus,ShieldCheck}from'lucide-vue-next';const rows=ref<any[]>([]),entities=ref<any[]>([]),open=ref(false),error=ref(''),name=ref(''),password=ref(''),entityId=ref(''),file=ref<File|null>(null);const cols=[{key:'name',label:'Certificado'},{key:'certificate_type',label:'Tipo'},{key:'serial_number',label:'Número de série'},{key:'valid_until',label:'Validade'},{key:'status',label:'Situação'}];async function load(){[rows.value,entities.value]=await Promise.all([api.get('/certificates').then(r=>r.data),api.get('/legal-entities').then(r=>r.data)])}async function save(){if(!file.value)return;const fd=new FormData();fd.append('name',name.value);fd.append('password',password.value);if(entityId.value)fd.append('legal_entity_id',entityId.value);fd.append('file',file.value);try{await api.post('/certificates',fd);open.value=false;await load()}catch(e){error.value=errorMessage(e)}}onMounted(()=>{load();window.addEventListener('tenant-changed',load)});onUnmounted(()=>window.removeEventListener('tenant-changed',load))
</script><template><PageHeader title="Certificados digitais" subtitle="Cofre criptografado para certificados A1 vinculados aos CNPJs"><button class="btn primary" @click="open=true"><Plus :size="16"/>Cadastrar certificado</button></PageHeader><div class="info-banner"><ShieldCheck/><div><strong>Proteção de ponta a ponta</strong><span>Arquivos PFX/P12 e senhas são criptografados antes do armazenamento.</span></div></div><section class="panel"><DataTable :columns="cols" :rows="rows"><template #cell-valid_until="{value}">{{value?new Date(value).toLocaleDateString('pt-BR'):'—'}}</template><template #cell-status="{value}"><StatusBadge :status="value"/></template></DataTable></section><Modal :open="open" title="Novo certificado A1" @close="open=false"><form class="form-grid" @submit.prevent="save"><label>Nome<input v-model="name" required/></label><label>Empresa<select v-model="entityId"><option value="">Uso geral do cliente</option><option v-for="e in entities" :value="e.id">{{e.legal_name}}</option></select></label><label>Senha do PFX<input v-model="password" type="password" required/></label><label>Arquivo<input type="file" accept=".pfx,.p12" required @change="file=($event.target as HTMLInputElement).files?.[0]||null"/></label><div v-if="error" class="alert danger span-2">{{error}}</div><div class="form-actions span-2"><button class="btn primary">Criptografar e salvar</button></div></form></Modal></template>
